package ma.autocarnet;
import java.time.*;import org.json.*;
final class MonthClosing {
 static String stage(JSONObject data,LocalDate today)throws Exception{JSONObject config=data.optJSONObject("monthlyClosing");if(config!=null&&!config.optBoolean("enabled",true))return null;if(today.getDayOfMonth()==today.lengthOfMonth())return "prepare:"+YearMonth.from(today);if(today.getDayOfMonth()>3)return null;String first=today.withDayOfMonth(1).toString();JSONObject v=data.getJSONObject("vehicle");if(v.optDouble("baselineKm",0)>0&&first.equals(v.optString("baselineDate")))return null;JSONArray entries=data.getJSONArray("entries");for(int i=0;i<entries.length();i++){JSONObject e=entries.getJSONObject(i);if(e.optBoolean("hasKm",true)&&first.equals(e.optString("date")))return null;}return "reading:"+YearMonth.from(today);}
 static String title(String lang){return lang.equals("ar")?"AutoCarnet · مراجعة الشهر":lang.equals("en")?"AutoCarnet · monthly review":"AutoCarnet · bilan de fin de mois";}
 static String message(String stage,String lang){boolean prepare=stage.startsWith("prepare:");if(lang.equals("ar"))return prepare?"غداً، سجّل العداد قبل أول رحلة وصوّره إن أردت. راجع المصاريف المنسية من «مراجعة الشهر».":"قراءة يوم 1 غير مسجلة. سجّل العداد بتاريخ القراءة الحقيقي وراجع معلومات الشهر الناقصة. لا تخمّن قراءة قديمة.";if(lang.equals("en"))return prepare?"Tomorrow, record the odometer before your first trip; a photo is optional. Check forgotten expenses in Review my month.":"The reading for the 1st is missing. Record the actual date and odometer, then review incomplete entries. Do not guess an old reading.";return prepare?"Demain, relevez le compteur avant le premier trajet ; photo facultative. Vérifiez les dépenses oubliées dans Revoir mon mois.":"Le compteur du 1er manque. Saisissez la date réelle du relevé puis vérifiez les informations du mois. N’inventez pas une ancienne lecture.";}
}
